import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Current transports and platform restrictions","description":"","frontmatter":{"title":"Current transports and platform restrictions","docId":"developer.transports","translationKey":"developer.transports","locale":"en","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a5fcd19211bdd279a0696cde31c26cc7444a128e50c3ca752489b25acb7cd9a","translationRevision":"6a5fcd19211bdd279a0696cde31c26cc7444a128e50c3ca752489b25acb7cd9a","order":200},"headers":[],"relativePath":"en/developer/transports.md","filePath":"en/developer/transports.md","lastUpdated":1795727787000}`),a={name:`en/developer/transports.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">Current transports and platform restrictions <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to “Current transports and platform restrictions”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Select the transport that actually exists for the target build and platform. Read <a href="./control-api.html">Control API</a> and <a href="./collaboration.html">collaboration</a>. A transport carries serialized operations; it must not introduce a second core or grant authority by itself.</p><h2 id="choose-the-boundary" tabindex="-1">Choose the boundary <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to “Choose the boundary”">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Current implementation</th><th>Important limit</th></tr></thead><tbody><tr><td>Desktop WebView</td><td>Wry IPC and shared control client</td><td>GUI/thread lifetime belongs to desktop</td></tr><tr><td>Local CLI</td><td>Unix socket or Windows named pipe; explicit stdio host</td><td>Same application home and owner</td></tr><tr><td>Local browser</td><td>Native loopback adapter plus <code>browser-transport.ts</code></td><td>Paired native host, not a mock or public remote server</td></tr><tr><td>Authenticated HTTPS/WSS gateway</td><td>SDK/browser transports with TLS, hello, grants and feature gates</td><td>Remote commands need an explicit grant</td></tr><tr><td>Installable remote-control plugin</td><td><code>tiktools.remote-control</code> over a WSS relay using <code>remote.controller.ticket</code></td><td>Plugin-owned; no remote code is compiled into the host</td></tr></tbody></table><p>The TypeScript transport interface lives at <code>src/web/shared/api/control-transport.ts</code>. Remote control is an installable plugin, not part of the host binary: every command crosses <code>HostCallPolicy</code> (<code>remote.command.dispatch</code>, <code>remote.pair.list</code>, <code>remote.grant.list</code>, <code>remote.grant.revoke</code>, <code>remote.controller.ticket</code>). This build has no native peer/RTC transport and no Cloud Teams host link.</p><h2 id="inspect-the-selected-route" tabindex="-1">Inspect the selected route <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to “Inspect the selected route”">​</a></h2><p>Discover the connected host&#39;s supported methods and capabilities before pairing or displaying a controller action:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span></code></pre></div><p>Pairing and grants are owned by the plugin: a controller ticket is short-lived and single-use, and <code>remote.grant.list</code> / <code>remote.grant.revoke</code> are the authoritative view. A relay connection proves transport only, never RPC authority.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Expected result and status”">​</a></h2><p>Local IPC and desktop transport are established paths. Remote control works through the installable plugin and an authenticated relay; it is not a second host runtime. Login codes are relayed to connected devices with a five-minute TTL, with an OAuth fallback when no account is configured. Android local IPC works with the instrumented <code>mobile</code> tooling (<code>info</code> / <code>exec</code> / <code>tty</code>); desktop native addons and WebViews remain unavailable there.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recovery”">​</a></h2><p>Treat disconnect as possible uncertainty for accepted operations. Reconnect must invalidate private projections, renegotiate identity and resume or snapshot bounded streams. Never downgrade certificate checks or fall back silently to a local owner after remote failure. Expired controller tickets and revoked grants must fail closed.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Operational details”">​</a></h2><p>Keep grants least-privilege and time-bounded; re-check them after every reconnect. Diagnose identity, ticket expiry, grant scope, relay reachability and frame size separately. Large frames fail framing validation rather than becoming partial RPCs. Test changed/revoked sessions with fixtures before real two-device acceptance.</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};